// Word lists for Word Hunt.
// ANSWERS: common everyday words picked for this game.
// ALLOWED: every 5-letter word from the "an-array-of-english-words" package (MIT License, (c) Titus Wormer), used to check guesses.
window.ANSWERS = "".match(/.{5}/g);
window.ALLOWED = new Set("".match(/.{5}/g));
ANSWERS.forEach(w => ALLOWED.add(w));
